import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `You are an automated ID Photo Biometric Compliance System. 
            Analyze this selfie frame for a formal ID/Passport photo.

            Strictly Check:
            1. Face visible and front-facing? (No profile views).
            2. Eyes open and looking at camera?
            3. Mouth closed (neutral expression)?
            4. Head straight (not tilted left/right/up/down)?
            5. Lighting sufficient (not too dark, no harsh shadows)?
            6. No objects covering face (hands, masks, dark glasses)?

            Output JSON. 
            - 'instruction' should be a short, direct command in Vietnamese (e.g., "Mở mắt to hơn", "Nhìn thẳng", "Ngẩng đầu lên").
            - If everything is perfect, 'instruction' should be "Giữ nguyên tư thế".
            ` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error) {
    console.error("AI Analysis Error", error);
    // Fallback to valid to not block user in case of network error
    return { isCompliant: true, status: 'VALID', feedback: 'Lỗi mạng', instruction: 'Chụp thủ công', faceDetected: true };
  }
};

/**
 * Processes the ID photo with strict biometric preservation rules.
 * CRITICAL: NO CROPPING OR RESIZING ALLOWED IN THIS STEP.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Constructing a structured prompt focused on IN-PLACE EDITING with HARD BIOMETRIC LOCK
  let prompt = `ROLE: Hệ thống bảo mật sinh trắc học & xử lý ảnh thẻ (Biometric Security & ID Photo Editor).
INPUT: Ảnh chân dung gốc.
OUTPUT: Ảnh đã xử lý nhưng BẮT BUỘC giữ nguyên 100% cấu trúc khuôn mặt.

================================================================
⚠️ YÊU CẦU BẮT BUỘC VỀ SINH TRẮC HỌC (ABSOLUTE CONSTRAINT)
================================================================
Trong mọi trường hợp, TUYỆT ĐỐI KHÔNG được:
1. Thay đổi hình dạng khuôn mặt (Face Shape/Jawline/Chin).
2. Biến dạng khuôn mặt dưới bất kỳ hình thức nào (Warping/Morphing).
3. Làm thay đổi đặc điểm nhận dạng sinh trắc học (Eyes, Nose, Mouth coordinates).

Cụ thể, KHÔNG được phép thay đổi:
- Khoảng cách giữa hai mắt.
- Vị trí, kích thước, hình dạng của mắt, mũi, miệng.
- Đường viền hàm, cằm, trán.
- Tỷ lệ tổng thể khuôn mặt.

NẾU việc thay áo hoặc làm đẹp có nguy cơ che lấp cằm, hoặc làm méo mặt:
-> BỎ QUA YÊU CẦU ĐÓ.
-> GIỮ NGUYÊN ẢNH GỐC tại vùng đó.
-> ƯU TIÊN: Sinh trắc học > Trang phục > Phông nền > Làm đẹp.

================================================================
NHIỆM VỤ CỤ THỂ (LAYER-BASED EDITING)
================================================================

LAYER 1: KHUÔN MẶT (LOCKED 🔒)
- Giữ nguyên pixel của mắt, mũi, miệng, khung xương mặt.
- Chỉ cho phép xử lý DA (Skin texture):
`;

  // Beauty Logic - Strict "Texture Only" instructions
  if (beautySettings.smoothSkin > 0) prompt += `  + Làm mịn da nhẹ (High Frequency Separation), giữ lại lỗ chân lông. KHÔNG làm mờ (Blur) đường nét.\n`;
  if (beautySettings.removeBlemishes) prompt += `  + Xóa mụn/thâm đỏ cục bộ. KHÔNG xóa nốt ruồi. KHÔNG xóa sẹo nhận dạng.\n`;
  if (beautySettings.fixLighting) prompt += `  + Cân bằng sáng (Dodge & Burn) nhẹ nhàng. Không thay đổi khối (3D Shape).\n`;
  if (beautySettings.fillHair) prompt += `  + Tóc con lòa xòa có thể xử lý, nhưng đường chân tóc (Hairline) phải giữ nguyên.\n`;

  prompt += `\nLAYER 2: TRANG PHỤC (REPLACEABLE)\n`;
  if (clothingPrompt) {
    prompt += `- Thay trang phục: "${clothingPrompt}".
- QUAN TRỌNG: Cổ áo MỚI phải nằm DƯỚI cằm và DƯỚI đường viền hàm của ảnh gốc.
- KHÔNG ĐƯỢC để cổ áo mới che khuất cằm hoặc làm thay đổi độ dài cổ.
- Ghép nối tự nhiên tại phần cổ, giữ nguyên màu da cổ gốc.`;
  } else {
    prompt += `- Giữ nguyên trang phục gốc.`;
  }

  prompt += `\n\nLAYER 3: PHÔNG NỀN (BACKGROUND)\n`;
  if (bgType === BackgroundType.WHITE) {
    prompt += `- Thay nền bằng TRẮNG TUYỆT ĐỐI (#FFFFFF). Tách tóc chính xác từng sợi.`;
  } else if (bgType === BackgroundType.BLUE) {
    prompt += `- Thay nền bằng XANH DƯƠNG (#0057B7).`;
  } else if (bgType === BackgroundType.GRAY) {
    prompt += `- Thay nền bằng XÁM TRUNG TÍNH (#E5E7EB).`;
  } else {
    prompt += `- Giữ nguyên nền.`;
  }

  prompt += `
================================================================
ĐỊNH DẠNG ĐẦU RA
================================================================
- Trả về ảnh JPEG chất lượng cao.
- Kích thước ảnh đầu ra PHẢI TRÙNG KHỚP hoàn toàn với ảnh đầu vào.
- Nếu không thể thực hiện yêu cầu mà không vi phạm sinh trắc học -> Trả về ảnh gần giống gốc nhất có thể.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { PhotoSize } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

// Strict State Machine for Biometric Validation
type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null); // Separate canvas for low-res analysis

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);

  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  // AI Validation State
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('Đang khởi động AI...');
  const [instruction, setInstruction] = useState<string>('');

  // Ref to track if an analysis request is currently in flight
  const isAnalyzingRef = useRef(false);
  const analysisIntervalRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    getDevices();
    startCamera();
    return () => {
      stopCamera();
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (selectedDeviceId) startCamera(selectedDeviceId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  // Start AI Analysis Loop when stream is active
  useEffect(() => {
    if (stream && !countdown) {
      // Run analysis every 1.5 seconds to avoid rate limits but keep it snappy
      analysisIntervalRef.current = setInterval(performAIAnalysis, 1500);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
  }, [stream, countdown]);

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;

    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');

      if (video.readyState === 4 && ctx) {
        // Draw small frame for analysis (reduce bandwidth/latency)
        canvas.width = 320;
        canvas.height = 240;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.6); // Low quality is enough for structure check

        // Show "Scanning" state briefly if we were previously idle
        if (validationStatus === 'searching') setValidationStatus('analyzing');

        const result = await analyzeIDPhotoFrame(base64);

        if (!result.faceDetected) {
           setValidationStatus('searching');
           setFeedbackMessage('Không tìm thấy mặt');
           setInstruction('Di chuyển vào khung hình');
        } else if (result.isCompliant) {
           setValidationStatus('valid');
           setFeedbackMessage('ĐẠT CHUẨN');
           setInstruction(result.instruction || 'Giữ nguyên tư thế!');
        } else {
           setValidationStatus('adjusting');
           setFeedbackMessage(result.feedback || 'Cần điều chỉnh');
           setInstruction(result.instruction || 'Chỉnh lại tư thế');
        }
      }
    } catch (err) {
      console.error("AI check failed", err);
    } finally {
      isAnalyzingRef.current = false;
    }
  };

  const getDevices = async () => {
    try {
      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);
      const canon = videoDevices.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
      if (canon) setSelectedDeviceId(canon.deviceId);
    } catch (err) {
      console.error("Error enumerating devices", err);
    }
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints: MediaStreamConstraints = {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          width: { ideal: 1920 }, // High resolution for quality crop
          height: { ideal: 1080 },
        },
        audio: false
      };
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
      setError('');
    } catch (err) {
      setError('Không thể truy cập camera. Kiểm tra kết nối.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = useCallback(() => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (context && video.videoWidth > 0 && video.videoHeight > 0) {
        // Crop logic...
        let targetRatio = 2/3; // Default 4x6
        if (selectedSize === PhotoSize.SIZE_5X5) targetRatio = 1;
        if (selectedSize === PhotoSize.SIZE_3X4) targetRatio = 3/4;

        const videoRatio = video.videoWidth / video.videoHeight;

        let sourceW, sourceH, startX, startY;

        if (videoRatio > targetRatio) {
          sourceH = video.videoHeight;
          sourceW = sourceH * targetRatio;
          startX = (video.videoWidth - sourceW) / 2;
          startY = 0;
        } else {
          sourceW = video.videoWidth;
          sourceH = sourceW / targetRatio;
          startX = 0;
          startY = (video.videoHeight - sourceH) / 2;
        }

        canvas.width = sourceW;
        canvas.height = sourceH;

        // Mirror effect for selfie camera
        context.translate(canvas.width, 0);
        context.scale(-1, 1); 

        context.drawImage(video, startX, startY, sourceW, sourceH, 0, 0, canvas.width, canvas.height);

        const dataUrl = canvas.toDataURL('image/jpeg', 1.0);
        onCapture(dataUrl);
      }
    }
  }, [onCapture, selectedSize]);

  useEffect(() => {
    if (countdown === null) return;

    if (countdown > 0) {
      const timer = setTimeout(() => {
        setCountdown(countdown - 1);
      }, 1000);
      return () => clearTimeout(timer);
    } else if (countdown === 0) {
      captureFrame();
      setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleCaptureClick = () => {
    // Allows manual override if AI is stuck, but encourages valid state
    setCountdown(3);
  };

  const isUSVisa = selectedSize === PhotoSize.SIZE_5X5;
  const is3x4 = selectedSize === PhotoSize.SIZE_3X4;

  // Determine UI Colors based on Strict State
  const getStatusColor = () => {
    switch (validationStatus) {
      case 'valid': return 'border-green-500 shadow-[0_0_30px_rgba(34,197,94,0.6)]';
      case 'adjusting': return 'border-yellow-400 shadow-[0_0_20px_rgba(250,204,21,0.4)]';
      case 'analyzing': return 'border-blue-400 shadow-[0_0_20px_rgba(96,165,250,0.4)]';
      case 'searching': 
      default: return 'border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.6)]';
    }
  };

  const getOverlayColor = () => {
     switch (validationStatus) {
      case 'valid': return '#22c55e'; // Green
      case 'adjusting': return '#facc15'; // Yellow
      case 'analyzing': return '#60a5fa'; // Blue
      default: return '#ef4444'; // Red
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-gray-900 relative select-none">

      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 z-50 p-4 flex justify-between items-start bg-gradient-to-b from-black/80 to-transparent pb-12">
        <select 
          value={selectedDeviceId}
          onChange={(e) => setSelectedDeviceId(e.target.value)}
          className="bg-black/50 text-white text-xs border border-gray-600 rounded px-3 py-1.5 outline-none backdrop-blur-md pointer-events-auto"
        >
          <option value="">-- Chọn Camera --</option>
          {devices.map((device, idx) => (
            <option key={device.deviceId || idx} value={device.deviceId}>
              {device.label || `Camera ${idx + 1}`}
            </option>
          ))}
        </select>

        {/* Realtime Feedback Status - LARGE & CENTRAL */}
        <div className={`
          absolute top-16 left-1/2 transform -translate-x-1/2
          px-6 py-3 rounded-xl backdrop-blur-md border-2 flex flex-col items-center gap-1 transition-all duration-300 min-w-[280px] text-center shadow-lg
          ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400 text-white scale-110' : 
            validationStatus === 'adjusting' ? 'bg-yellow-600/80 border-yellow-400 text-white' :
            validationStatus === 'analyzing' ? 'bg-blue-600/80 border-blue-400 text-white' :
            'bg-red-600/80 border-red-500 text-white'}
        `}>
          <div className="flex items-center gap-2">
             {validationStatus === 'valid' ? (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
             ) : (
                <div className="animate-spin w-4 h-4 border-2 border-current border-t-transparent rounded-full" />
             )}
             <span className="font-bold text-sm tracking-wide uppercase">{feedbackMessage}</span>
          </div>
          <span className="text-xs font-medium opacity-90">{instruction}</span>
        </div>
      </div>

      {error && <div className="absolute z-50 bg-red-600 text-white p-4 rounded-lg shadow-xl font-bold animate-pulse">{error}</div>}

      {/* Camera Feed with Aspect Ratio Crop Preview */}
      <div 
        className={`relative transition-all duration-300 bg-black rounded-lg overflow-hidden flex items-center justify-center border-4
          ${isUSVisa ? 'aspect-square h-[75vh]' : is3x4 ? 'aspect-[3/4] h-[75vh]' : 'aspect-[2/3] h-[75vh]'}
          ${getStatusColor()}
        `}
      >
        <video
          ref={videoRef}
          autoPlay
          playsInline
          className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" 
        />

        {/* =============================================
            ENHANCED SVG OVERLAY WITH MASKING
           ============================================= */}
        <div className="relative z-10 w-full h-full">
          {/* Scanning Effect */}
          {(validationStatus === 'searching' || validationStatus === 'analyzing') && (
            <div className="absolute top-0 left-0 w-full h-1 bg-white/80 shadow-[0_0_15px_rgba(255,255,255,1)] animate-[scan_1.5s_ease-in-out_infinite]" />
          )}

          {isUSVisa ? (
            // --- VISA MỸ (5x5) GUIDE ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none transition-colors duration-300">
               <defs>
                 <mask id="faceMaskUS">
                   <rect x="0" y="0" width="100" height="100" fill="white" />
                   {/* Hole for Face (rx=35, ry=42) */}
                   <ellipse cx="50" cy="50" rx="35" ry="42" fill="black" />
                 </mask>
               </defs>

               {/* Darkened Background (Masked) */}
               <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#faceMaskUS)" />

               {/* Center Line */}
               <line x1="50" y1="0" x2="50" y2="100" stroke={getOverlayColor()} strokeWidth="0.2" strokeDasharray="2,2" />

               {/* Eye Zone (28mm-35mm from bottom) */}
               <rect x="0" y="31" width="100" height="13" fill={validationStatus === 'valid' ? "rgba(34, 197, 94, 0.15)" : "rgba(239, 68, 68, 0.1)"} stroke="none" />
               <line x1="0" y1="31" x2="100" y2="31" stroke={getOverlayColor()} strokeWidth="0.3" strokeDasharray="4,2" />
               <line x1="0" y1="44" x2="100" y2="44" stroke={getOverlayColor()} strokeWidth="0.3" strokeDasharray="4,2" />

               {/* Head Size Limit Markers */}
               <line x1="40" y1="10" x2="60" y2="10" stroke={getOverlayColor()} strokeWidth="0.5" />
               <text x="50" y="8" fill="white" fontSize="2.5" textAnchor="middle">Đỉnh đầu (Max)</text>

               <line x1="40" y1="88" x2="60" y2="88" stroke={getOverlayColor()} strokeWidth="0.5" />
               <text x="50" y="92" fill="white" fontSize="2.5" textAnchor="middle">Cằm (Min)</text>

               {/* Oval Outline */}
               <ellipse cx="50" cy="50" rx="35" ry="42" fill="none" stroke={getOverlayColor()} strokeWidth={validationStatus === 'valid' ? "1" : "0.5"} strokeDasharray={validationStatus === 'valid' ? "0" : "6,4"} />
            </svg>
          ) : (
             // --- STANDARD 4x6 / 3x4 GUIDE (75% FACE AREA) ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none transition-colors duration-300">
              <defs>
                 <mask id="faceMaskStd">
                   <rect x="0" y="0" width="100" height="100" fill="white" />
                   {/* Hole for Face (rx=32, ry=42) - Covers ~75% height */}
                   <ellipse cx="50" cy="49" rx="32" ry="42" fill="black" />
                 </mask>
               </defs>

               {/* Darkened Background */}
               <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#faceMaskStd)" />

              <line x1="50" y1="0" x2="50" y2="100" stroke={getOverlayColor()} strokeWidth="0.2" strokeDasharray="2,2" />

              {/* Top of Head Marker (~8-10%) */}
              <line x1="30" y1="8" x2="70" y2="8" stroke={getOverlayColor()} strokeWidth="0.5" />
              <text x="50" y="6" fill="white" fontSize="2.5" textAnchor="middle" style={{textShadow: '0 1px 2px black'}}>ĐỈNH ĐẦU</text>

              {/* Chin Marker (~90%) */}
              <line x1="35" y1="90" x2="65" y2="90" stroke={getOverlayColor()} strokeWidth="0.5" />
              <text x="50" y="94" fill="white" fontSize="2.5" textAnchor="middle" style={{textShadow: '0 1px 2px black'}}>CẰM</text>

              {/* Eye Line (~40%) */}
              <line x1="15" y1="40" x2="85" y2="40" stroke={getOverlayColor()} strokeWidth="0.5" strokeDasharray="4,4" />
              <text x="88" y="39" fill="white" fontSize="2.5" fontWeight="bold" style={{textShadow: '0 1px 2px black'}}>MẮT</text>

              {/* OVAL GUIDE - 75% AREA */}
              <ellipse cx="50" cy="49" rx="32" ry="42" fill="none" stroke={getOverlayColor()} strokeWidth={validationStatus === 'valid' ? "1" : "0.5"} strokeDasharray={validationStatus === 'valid' ? "0" : "2,2"} />

              <text x="50" y="98" fill="white" fontSize="3" textAnchor="middle" fontWeight="bold" style={{textShadow: '0 1px 2px black'}}>
                {is3x4 ? 'THẺ 3x4 (75% MẶT)' : 'HỘ CHIẾU 4x6 (75% MẶT)'}
              </text>
            </svg>
          )}
        </div>

        {/* Countdown Overlay */}
        {countdown !== null && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-40 backdrop-blur-sm">
            <span className="text-[120px] font-bold text-white animate-ping">{countdown}</span>
          </div>
        )}
      </div>

      {/* Capture Controls - STRICTLY DISABLED WHEN NOT VALID */}
      <div className="absolute bottom-8 left-0 right-0 flex flex-col justify-end items-center gap-4 z-50 pointer-events-auto">
        <div className={`text-sm font-bold px-4 py-1.5 rounded-full shadow-lg backdrop-blur transition-colors ${validationStatus === 'valid' ? 'bg-green-500 text-white' : 'bg-gray-800/80 text-gray-400'}`}>
           {validationStatus === 'valid' ? '✔ AI CHẤP NHẬN' : '⚠️ AI ĐANG KIỂM TRA QUY ĐỊNH'}
        </div>

        <button
          onClick={handleCaptureClick}
          disabled={countdown !== null}
          className={`
            w-20 h-20 rounded-full border-4 transition-all duration-300 flex items-center justify-center shadow-2xl relative
            ${validationStatus === 'valid' 
              ? 'bg-white border-green-500 hover:border-green-400 hover:scale-105 active:scale-95 cursor-pointer ring-4 ring-green-500/30' 
              : 'bg-gray-700 border-gray-600 opacity-90 cursor-pointer'} 
          `}
          // Note: Removed 'disabled' for validationStatus to allow manual override if AI is fussy, 
          // but visual cues strongly suggest waiting for green.
        >
           {/* Inner Circle / Lock Icon */}
           <div className={`w-16 h-16 rounded-full transition-all duration-300 flex items-center justify-center ${validationStatus === 'valid' ? 'bg-green-600' : 'bg-gray-600'}`}>
              {validationStatus !== 'valid' && (
                 <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
              )}
           </div>
        </button>
      </div>

      <canvas ref={canvasRef} className="hidden" />
      <canvas ref={analysisCanvasRef} className="hidden" />

      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

export default CameraCapture;

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `You are an automated ID Photo Biometric Compliance System. 
            Analyze this selfie frame for a formal ID/Passport photo.

            Strictly Check:
            1. Face visible and front-facing? (No profile views).
            2. Eyes open and looking at camera?
            3. Mouth closed (neutral expression)?
            4. Head straight (not tilted left/right/up/down)?
            5. Lighting sufficient (not too dark, no harsh shadows)?
            6. No objects covering face (hands, masks, dark glasses)?

            Output JSON. 
            - 'instruction' should be a short, direct command in Vietnamese (e.g., "Mở mắt to hơn", "Nhìn thẳng", "Ngẩng đầu lên").
            - If everything is perfect, 'instruction' should be "Giữ nguyên tư thế".
            ` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error) {
    console.error("AI Analysis Error", error);
    // Fallback to valid to not block user in case of network error
    return { isCompliant: true, status: 'VALID', feedback: 'Lỗi mạng', instruction: 'Chụp thủ công', faceDetected: true };
  }
};

/**
 * Processes the ID photo with strict biometric preservation rules.
 * CRITICAL: NO CROPPING OR RESIZING ALLOWED IN THIS STEP.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Constructing a structured prompt focused on IN-PLACE EDITING with HARD BIOMETRIC LOCK
  let prompt = `ROLE: Hệ thống bảo mật sinh trắc học & xử lý ảnh thẻ (Biometric Security & ID Photo Editor).
INPUT: Ảnh chân dung gốc.
OUTPUT: Ảnh đã xử lý nhưng BẮT BUỘC giữ nguyên 100% cấu trúc khuôn mặt.

================================================================
⚠️ YÊU CẦU BẮT BUỘC VỀ SINH TRẮC HỌC (ABSOLUTE CONSTRAINT)
================================================================
Trong mọi trường hợp, TUYỆT ĐỐI KHÔNG được:
1. Thay đổi hình dạng khuôn mặt (Face Shape/Jawline/Chin).
2. Biến dạng khuôn mặt dưới bất kỳ hình thức nào (Warping/Morphing).
3. Làm thay đổi đặc điểm nhận dạng sinh trắc học (Eyes, Nose, Mouth coordinates).

Cụ thể, KHÔNG được phép thay đổi:
- Khoảng cách giữa hai mắt.
- Vị trí, kích thước, hình dạng của mắt, mũi, miệng.
- Đường viền hàm, cằm, trán.
- Tỷ lệ tổng thể khuôn mặt.

NẾU việc thay áo hoặc làm đẹp có nguy cơ che lấp cằm, hoặc làm méo mặt:
-> BỎ QUA YÊU CẦU ĐÓ.
-> GIỮ NGUYÊN ẢNH GỐC tại vùng đó.
-> ƯU TIÊN: Sinh trắc học > Trang phục > Phông nền > Làm đẹp.

================================================================
NHIỆM VỤ CỤ THỂ (LAYER-BASED EDITING)
================================================================

LAYER 1: KHUÔN MẶT (LOCKED 🔒)
- Giữ nguyên pixel của mắt, mũi, miệng, khung xương mặt.
- Chỉ cho phép xử lý DA (Skin texture):
`;

  // Beauty Logic - Strict "Texture Only" instructions
  if (beautySettings.smoothSkin > 0) prompt += `  + Làm mịn da nhẹ (High Frequency Separation), giữ lại lỗ chân lông. KHÔNG làm mờ (Blur) đường nét.\n`;
  if (beautySettings.removeBlemishes) prompt += `  + Xóa mụn/thâm đỏ cục bộ. KHÔNG xóa nốt ruồi. KHÔNG xóa sẹo nhận dạng.\n`;
  if (beautySettings.fixLighting) prompt += `  + Cân bằng sáng (Dodge & Burn) nhẹ nhàng. Không thay đổi khối (3D Shape).\n`;
  if (beautySettings.fillHair) prompt += `  + Tóc con lòa xòa có thể xử lý, nhưng đường chân tóc (Hairline) phải giữ nguyên.\n`;

  prompt += `\nLAYER 2: TRANG PHỤC (REPLACEABLE)\n`;
  if (clothingPrompt) {
    prompt += `- Thay trang phục: "${clothingPrompt}".
- QUAN TRỌNG: Cổ áo MỚI phải nằm DƯỚI cằm và DƯỚI đường viền hàm của ảnh gốc.
- KHÔNG ĐƯỢC để cổ áo mới che khuất cằm hoặc làm thay đổi độ dài cổ.
- Ghép nối tự nhiên tại phần cổ, giữ nguyên màu da cổ gốc.`;
  } else {
    prompt += `- Giữ nguyên trang phục gốc.`;
  }

  prompt += `\n\nLAYER 3: PHÔNG NỀN (BACKGROUND)\n`;
  if (bgType === BackgroundType.WHITE) {
    prompt += `- Thay nền bằng TRẮNG TUYỆT ĐỐI (#FFFFFF). Tách tóc chính xác từng sợi.`;
  } else if (bgType === BackgroundType.BLUE) {
    prompt += `- Thay nền bằng XANH DƯƠNG (#0057B7).`;
  } else if (bgType === BackgroundType.GRAY) {
    prompt += `- Thay nền bằng XÁM TRUNG TÍNH (#E5E7EB).`;
  } else {
    prompt += `- Giữ nguyên nền.`;
  }

  prompt += `
================================================================
ĐỊNH DẠNG ĐẦU RA
================================================================
- Trả về ảnh JPEG chất lượng cao.
- Kích thước ảnh đầu ra PHẢI TRÙNG KHỚP hoàn toàn với ảnh đầu vào.
- Nếu không thể thực hiện yêu cầu mà không vi phạm sinh trắc học -> Trả về ảnh gần giống gốc nhất có thể.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { PhotoSize } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

// Strict State Machine for Biometric Validation
type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null); // Separate canvas for low-res analysis

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);

  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  // AI Validation State
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('Đang khởi động AI...');
  const [instruction, setInstruction] = useState<string>('');

  // Ref to track if an analysis request is currently in flight
  const isAnalyzingRef = useRef(false);
  // Using ReturnType<typeof setInterval> to handle both NodeJS and Browser environments
  const analysisIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    getDevices();
    startCamera();
    return () => {
      stopCamera();
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (selectedDeviceId) startCamera(selectedDeviceId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  // Start AI Analysis Loop when stream is active
  useEffect(() => {
    if (stream && !countdown) {
      // Run analysis every 1.5 seconds to avoid rate limits but keep it snappy
      analysisIntervalRef.current = setInterval(performAIAnalysis, 1500);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
  }, [stream, countdown]);

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;

    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');

      if (video.readyState === 4 && ctx) {
        // Draw small frame for analysis (reduce bandwidth/latency)
        canvas.width = 320;
        canvas.height = 240;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.6); // Low quality is enough for structure check

        // Show "Scanning" state briefly if we were previously idle
        if (validationStatus === 'searching') setValidationStatus('analyzing');

        const result = await analyzeIDPhotoFrame(base64);

        if (!result.faceDetected) {
           setValidationStatus('searching');
           setFeedbackMessage('Không tìm thấy mặt');
           setInstruction('Di chuyển vào khung hình');
        } else if (result.isCompliant) {
           setValidationStatus('valid');
           setFeedbackMessage('ĐẠT CHUẨN');
           setInstruction(result.instruction || 'Giữ nguyên tư thế!');
        } else {
           setValidationStatus('adjusting');
           setFeedbackMessage(result.feedback || 'Cần điều chỉnh');
           setInstruction(result.instruction || 'Chỉnh lại tư thế');
        }
      }
    } catch (err) {
      console.error("AI check failed", err);
    } finally {
      isAnalyzingRef.current = false;
    }
  };

  const getDevices = async () => {
    try {
      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);
      const canon = videoDevices.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
      if (canon) setSelectedDeviceId(canon.deviceId);
    } catch (err) {
      console.error("Error enumerating devices", err);
    }
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints: MediaStreamConstraints = {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          width: { ideal: 1920 }, // High resolution for quality crop
          height: { ideal: 1080 },
        },
        audio: false
      };
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
      setError('');
    } catch (err) {
      setError('Không thể truy cập camera. Kiểm tra kết nối.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = useCallback(() => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (context && video.videoWidth > 0 && video.videoHeight > 0) {
        // Crop logic...
        let targetRatio = 2/3; // Default 4x6
        if (selectedSize === PhotoSize.SIZE_5X5) targetRatio = 1;
        if (selectedSize === PhotoSize.SIZE_3X4) targetRatio = 3/4;

        const videoRatio = video.videoWidth / video.videoHeight;

        let sourceW, sourceH, startX, startY;

        if (videoRatio > targetRatio) {
          sourceH = video.videoHeight;
          sourceW = sourceH * targetRatio;
          startX = (video.videoWidth - sourceW) / 2;
          startY = 0;
        } else {
          sourceW = video.videoWidth;
          sourceH = sourceW / targetRatio;
          startX = 0;
          startY = (video.videoHeight - sourceH) / 2;
        }

        canvas.width = sourceW;
        canvas.height = sourceH;

        // Mirror effect for selfie camera
        context.translate(canvas.width, 0);
        context.scale(-1, 1); 

        context.drawImage(video, startX, startY, sourceW, sourceH, 0, 0, canvas.width, canvas.height);

        const dataUrl = canvas.toDataURL('image/jpeg', 1.0);
        onCapture(dataUrl);
      }
    }
  }, [onCapture, selectedSize]);

  useEffect(() => {
    if (countdown === null) return;

    if (countdown > 0) {
      const timer = setTimeout(() => {
        setCountdown(countdown - 1);
      }, 1000);
      return () => clearTimeout(timer);
    } else if (countdown === 0) {
      captureFrame();
      setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleCaptureClick = () => {
    // Allows manual override if AI is stuck, but encourages valid state
    setCountdown(3);
  };

  const isUSVisa = selectedSize === PhotoSize.SIZE_5X5;
  const is3x4 = selectedSize === PhotoSize.SIZE_3X4;

  // Determine UI Colors based on Strict State
  const getStatusColor = () => {
    switch (validationStatus) {
      case 'valid': return 'border-green-500 shadow-[0_0_30px_rgba(34,197,94,0.6)]';
      case 'adjusting': return 'border-yellow-400 shadow-[0_0_20px_rgba(250,204,21,0.4)]';
      case 'analyzing': return 'border-blue-400 shadow-[0_0_20px_rgba(96,165,250,0.4)]';
      case 'searching': 
      default: return 'border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.6)]';
    }
  };

  const getOverlayColor = () => {
     switch (validationStatus) {
      case 'valid': return '#22c55e'; // Green
      case 'adjusting': return '#facc15'; // Yellow
      case 'analyzing': return '#60a5fa'; // Blue
      default: return '#ef4444'; // Red
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-gray-900 relative select-none">

      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 z-50 p-4 flex justify-between items-start bg-gradient-to-b from-black/80 to-transparent pb-12">
        <select 
          value={selectedDeviceId}
          onChange={(e) => setSelectedDeviceId(e.target.value)}
          className="bg-black/50 text-white text-xs border border-gray-600 rounded px-3 py-1.5 outline-none backdrop-blur-md pointer-events-auto"
        >
          <option value="">-- Chọn Camera --</option>
          {devices.map((device, idx) => (
            <option key={device.deviceId || idx} value={device.deviceId}>
              {device.label || `Camera ${idx + 1}`}
            </option>
          ))}
        </select>

        {/* Realtime Feedback Status - LARGE & CENTRAL */}
        <div className={`
          absolute top-16 left-1/2 transform -translate-x-1/2
          px-6 py-3 rounded-xl backdrop-blur-md border-2 flex flex-col items-center gap-1 transition-all duration-300 min-w-[280px] text-center shadow-lg
          ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400 text-white scale-110' : 
            validationStatus === 'adjusting' ? 'bg-yellow-600/80 border-yellow-400 text-white' :
            validationStatus === 'analyzing' ? 'bg-blue-600/80 border-blue-400 text-white' :
            'bg-red-600/80 border-red-500 text-white'}
        `}>
          <div className="flex items-center gap-2">
             {validationStatus === 'valid' ? (
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
             ) : (
                <div className="animate-spin w-4 h-4 border-2 border-current border-t-transparent rounded-full" />
             )}
             <span className="font-bold text-sm tracking-wide uppercase">{feedbackMessage}</span>
          </div>
          <span className="text-xs font-medium opacity-90">{instruction}</span>
        </div>
      </div>

      {error && <div className="absolute z-50 bg-red-600 text-white p-4 rounded-lg shadow-xl font-bold animate-pulse">{error}</div>}

      {/* Camera Feed with Aspect Ratio Crop Preview */}
      <div 
        className={`relative transition-all duration-300 bg-black rounded-lg overflow-hidden flex items-center justify-center border-4
          ${isUSVisa ? 'aspect-square h-[75vh]' : is3x4 ? 'aspect-[3/4] h-[75vh]' : 'aspect-[2/3] h-[75vh]'}
          ${getStatusColor()}
        `}
      >
        <video
          ref={videoRef}
          autoPlay
          playsInline
          className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" 
        />

        {/* =============================================
            ENHANCED SVG OVERLAY WITH MASKING
           ============================================= */}
        <div className="relative z-10 w-full h-full">
          {/* Scanning Effect */}
          {(validationStatus === 'searching' || validationStatus === 'analyzing') && (
            <div className="absolute top-0 left-0 w-full h-1 bg-white/80 shadow-[0_0_15px_rgba(255,255,255,1)] animate-[scan_1.5s_ease-in-out_infinite]" />
          )}

          {isUSVisa ? (
            // --- VISA MỸ (5x5) GUIDE ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none transition-colors duration-300">
               <defs>
                 <mask id="faceMaskUS">
                   <rect x="0" y="0" width="100" height="100" fill="white" />
                   {/* Hole for Face (rx=35, ry=42) */}
                   <ellipse cx="50" cy="50" rx="35" ry="42" fill="black" />
                 </mask>
               </defs>

               {/* Darkened Background (Masked) */}
               <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#faceMaskUS)" />

               {/* Center Line */}
               <line x1="50" y1="0" x2="50" y2="100" stroke={getOverlayColor()} strokeWidth="0.2" strokeDasharray="2,2" />

               {/* Eye Zone (28mm-35mm from bottom) */}
               <rect x="0" y="31" width="100" height="13" fill={validationStatus === 'valid' ? "rgba(34, 197, 94, 0.15)" : "rgba(239, 68, 68, 0.1)"} stroke="none" />
               <line x1="0" y1="31" x2="100" y2="31" stroke={getOverlayColor()} strokeWidth="0.3" strokeDasharray="4,2" />
               <line x1="0" y1="44" x2="100" y2="44" stroke={getOverlayColor()} strokeWidth="0.3" strokeDasharray="4,2" />

               {/* Head Size Limit Markers */}
               <line x1="40" y1="10" x2="60" y2="10" stroke={getOverlayColor()} strokeWidth="0.5" />
               <text x="50" y="8" fill="white" fontSize="2.5" textAnchor="middle">Đỉnh đầu (Max)</text>

               <line x1="40" y1="88" x2="60" y2="88" stroke={getOverlayColor()} strokeWidth="0.5" />
               <text x="50" y="92" fill="white" fontSize="2.5" textAnchor="middle">Cằm (Min)</text>

               {/* Oval Outline */}
               <ellipse cx="50" cy="50" rx="35" ry="42" fill="none" stroke={getOverlayColor()} strokeWidth={validationStatus === 'valid' ? "1" : "0.5"} strokeDasharray={validationStatus === 'valid' ? "0" : "6,4"} />
            </svg>
          ) : (
             // --- STANDARD 4x6 / 3x4 GUIDE (75% FACE AREA) ---
            <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none transition-colors duration-300">
              <defs>
                 <mask id="faceMaskStd">
                   <rect x="0" y="0" width="100" height="100" fill="white" />
                   {/* Hole for Face (rx=32, ry=42) - Covers ~75% height */}
                   <ellipse cx="50" cy="49" rx="32" ry="42" fill="black" />
                 </mask>
               </defs>

               {/* Darkened Background */}
               <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#faceMaskStd)" />

              <line x1="50" y1="0" x2="50" y2="100" stroke={getOverlayColor()} strokeWidth="0.2" strokeDasharray="2,2" />

              {/* Top of Head Marker (~8-10%) */}
              <line x1="30" y1="8" x2="70" y2="8" stroke={getOverlayColor()} strokeWidth="0.5" />
              <text x="50" y="6" fill="white" fontSize="2.5" textAnchor="middle" style={{textShadow: '0 1px 2px black'}}>ĐỈNH ĐẦU</text>

              {/* Chin Marker (~90%) */}
              <line x1="35" y1="90" x2="65" y2="90" stroke={getOverlayColor()} strokeWidth="0.5" />
              <text x="50" y="94" fill="white" fontSize="2.5" textAnchor="middle" style={{textShadow: '0 1px 2px black'}}>CẰM</text>

              {/* Eye Line (~40%) */}
              <line x1="15" y1="40" x2="85" y2="40" stroke={getOverlayColor()} strokeWidth="0.5" strokeDasharray="4,4" />
              <text x="88" y="39" fill="white" fontSize="2.5" fontWeight="bold" style={{textShadow: '0 1px 2px black'}}>MẮT</text>

              {/* OVAL GUIDE - 75% AREA */}
              <ellipse cx="50" cy="49" rx="32" ry="42" fill="none" stroke={getOverlayColor()} strokeWidth={validationStatus === 'valid' ? "1" : "0.5"} strokeDasharray={validationStatus === 'valid' ? "0" : "2,2"} />

              <text x="50" y="98" fill="white" fontSize="3" textAnchor="middle" fontWeight="bold" style={{textShadow: '0 1px 2px black'}}>
                {is3x4 ? 'THẺ 3x4 (75% MẶT)' : 'HỘ CHIẾU 4x6 (75% MẶT)'}
              </text>
            </svg>
          )}
        </div>

        {/* Countdown Overlay */}
        {countdown !== null && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-40 backdrop-blur-sm">
            <span className="text-[120px] font-bold text-white animate-ping">{countdown}</span>
          </div>
        )}
      </div>

      {/* Capture Controls - STRICTLY DISABLED WHEN NOT VALID */}
      <div className="absolute bottom-8 left-0 right-0 flex flex-col justify-end items-center gap-4 z-50 pointer-events-auto">
        <div className={`text-sm font-bold px-4 py-1.5 rounded-full shadow-lg backdrop-blur transition-colors ${validationStatus === 'valid' ? 'bg-green-500 text-white' : 'bg-gray-800/80 text-gray-400'}`}>
           {validationStatus === 'valid' ? '✔ AI CHẤP NHẬN' : '⚠️ AI ĐANG KIỂM TRA QUY ĐỊNH'}
        </div>

        <button
          onClick={handleCaptureClick}
          disabled={countdown !== null}
          className={`
            w-20 h-20 rounded-full border-4 transition-all duration-300 flex items-center justify-center shadow-2xl relative
            ${validationStatus === 'valid' 
              ? 'bg-white border-green-500 hover:border-green-400 hover:scale-105 active:scale-95 cursor-pointer ring-4 ring-green-500/30' 
              : 'bg-gray-700 border-gray-600 opacity-90 cursor-pointer'} 
          `}
          // Note: Removed 'disabled' for validationStatus to allow manual override if AI is fussy, 
          // but visual cues strongly suggest waiting for green.
        >
           {/* Inner Circle / Lock Icon */}
           <div className={`w-16 h-16 rounded-full transition-all duration-300 flex items-center justify-center ${validationStatus === 'valid' ? 'bg-green-600' : 'bg-gray-600'}`}>
              {validationStatus !== 'valid' && (
                 <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
              )}
           </div>
        </button>
      </div>

      <canvas ref={canvasRef} className="hidden" />
      <canvas ref={analysisCanvasRef} className="hidden" />

      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

export default CameraCapture;

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

// Schema for the AI Camera analysis response
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Analyzes a webcam frame for ID photo compliance.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  if (!API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `You are an automated ID Photo Biometric Compliance System. 
            Analyze this selfie frame for a formal ID/Passport photo.

            Strictly Check:
            1. Face visible and front-facing? (No profile views).
            2. Eyes open and looking at camera?
            3. Mouth closed (neutral expression)?
            4. Head straight (not tilted left/right/up/down)?
            5. Lighting sufficient (not too dark, no harsh shadows)?
            6. No objects covering face (hands, masks, dark glasses)?

            Output JSON. 
            - 'instruction' should be a short, direct command in Vietnamese (e.g., "Mở mắt to hơn", "Nhìn thẳng", "Ngẩng đầu lên").
            - If everything is perfect, 'instruction' should be "Giữ nguyên tư thế".
            ` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error) {
    console.error("AI Analysis Error", error);
    // Fallback to valid to not block user in case of network error
    return { isCompliant: true, status: 'VALID', feedback: 'Lỗi mạng', instruction: 'Chụp thủ công', faceDetected: true };
  }
};

/**
 * Processes the ID photo with strict biometric preservation rules.
 * CRITICAL: NO CROPPING OR RESIZING ALLOWED IN THIS STEP.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings,
  size: PhotoSize
): Promise<string> => {
  if (!API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Constructing a structured prompt focused on IN-PLACE EDITING with HARD BIOMETRIC LOCK
  let prompt = `ROLE: Hệ thống bảo mật sinh trắc học & xử lý ảnh thẻ (Biometric Security & ID Photo Editor).
INPUT: Ảnh chân dung gốc.
OUTPUT: Ảnh đã xử lý nhưng BẮT BUỘC giữ nguyên 100% cấu trúc khuôn mặt.

================================================================
⚠️ YÊU CẦU BẮT BUỘC VỀ SINH TRẮC HỌC (ABSOLUTE CONSTRAINT)
================================================================
Trong mọi trường hợp, TUYỆT ĐỐI KHÔNG được:
1. Thay đổi hình dạng khuôn mặt (Face Shape/Jawline/Chin).
2. Biến dạng khuôn mặt dưới bất kỳ hình thức nào (Warping/Morphing).
3. Làm thay đổi đặc điểm nhận dạng sinh trắc học (Eyes, Nose, Mouth coordinates).

Cụ thể, KHÔNG được phép thay đổi:
- Khoảng cách giữa hai mắt.
- Vị trí, kích thước, hình dạng của mắt, mũi, miệng.
- Đường viền hàm, cằm, trán.
- Tỷ lệ tổng thể khuôn mặt.

NẾU việc thay áo hoặc làm đẹp có nguy cơ che lấp cằm, hoặc làm méo mặt:
-> BỎ QUA YÊU CẦU ĐÓ.
-> GIỮ NGUYÊN ẢNH GỐC tại vùng đó.
-> ƯU TIÊN: Sinh trắc học > Trang phục > Phông nền > Làm đẹp.

================================================================
NHIỆM VỤ CỤ THỂ (LAYER-BASED EDITING)
================================================================

LAYER 1: KHUÔN MẶT (LOCKED 🔒)
- Giữ nguyên pixel của mắt, mũi, miệng, khung xương mặt.
- Chỉ cho phép xử lý DA (Skin texture):
`;

  // Beauty Logic - Strict "Texture Only" instructions
  if (beautySettings.smoothSkin > 0) prompt += `  + Làm mịn da nhẹ (High Frequency Separation), giữ lại lỗ chân lông. KHÔNG làm mờ (Blur) đường nét.\n`;
  if (beautySettings.removeBlemishes) prompt += `  + Xóa mụn/thâm đỏ cục bộ. KHÔNG xóa nốt ruồi. KHÔNG xóa sẹo nhận dạng.\n`;
  if (beautySettings.fixLighting) prompt += `  + Cân bằng sáng (Dodge & Burn) nhẹ nhàng. Không thay đổi khối (3D Shape).\n`;
  if (beautySettings.fillHair) prompt += `  + Tóc con lòa xòa có thể xử lý, nhưng đường chân tóc (Hairline) phải giữ nguyên.\n`;

  prompt += `\nLAYER 2: TRANG PHỤC (REPLACEABLE)\n`;
  if (clothingPrompt) {
    prompt += `- Thay trang phục: "${clothingPrompt}".
- QUAN TRỌNG: Cổ áo MỚI phải nằm DƯỚI cằm và DƯỚI đường viền hàm của ảnh gốc.
- KHÔNG ĐƯỢC để cổ áo mới che khuất cằm hoặc làm thay đổi độ dài cổ.
- Ghép nối tự nhiên tại phần cổ, giữ nguyên màu da cổ gốc.`;
  } else {
    prompt += `- Giữ nguyên trang phục gốc.`;
  }

  prompt += `\n\nLAYER 3: PHÔNG NỀN (BACKGROUND)\n`;
  if (bgType === BackgroundType.WHITE) {
    prompt += `- Thay nền bằng TRẮNG TUYỆT ĐỐI (#FFFFFF). Tách tóc chính xác từng sợi.`;
  } else if (bgType === BackgroundType.BLUE) {
    prompt += `- Thay nền bằng XANH DƯƠNG (#0057B7).`;
  } else if (bgType === BackgroundType.GRAY) {
    prompt += `- Thay nền bằng XÁM TRUNG TÍNH (#E5E7EB).`;
  } else {
    prompt += `- Giữ nguyên nền.`;
  }

  prompt += `
================================================================
ĐỊNH DẠNG ĐẦU RA
================================================================
- Trả về ảnh JPEG chất lượng cao.
- Kích thước ảnh đầu ra PHẢI TRÙNG KHỚP hoàn toàn với ảnh đầu vào.
- Nếu không thể thực hiện yêu cầu mà không vi phạm sinh trắc học -> Trả về ảnh gần giống gốc nhất có thể.
`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: prompt
          }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/jpeg;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("Không nhận được dữ liệu ảnh từ Gemini.");

  } catch (error) {
    console.error("Gemini processing error:", error);
    throw error;
  }
};

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { PhotoSize } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

// Strict State Machine for Biometric Validation
type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null); // Separate canvas for low-res analysis

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);

  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');

  // AI Validation State
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('Đang khởi động AI...');
  const [instruction, setInstruction] = useState<string>('');

  // Ref to track if an analysis request is currently in flight
  const isAnalyzingRef = useRef(false);
  // Using ReturnType<typeof setInterval> to handle both NodeJS and Browser environments
  const analysisIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    getDevices();
    startCamera();
    return () => {
      stopCamera();
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (selectedDeviceId) startCamera(selectedDeviceId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDeviceId]);

  // Start AI Analysis Loop when stream is active
  useEffect(() => {
    if (stream && !countdown) {
      // Run analysis every 1.5 seconds to avoid rate limits but keep it snappy
      analysisIntervalRef.current = setInterval(performAIAnalysis, 1500);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
  }, [stream, countdown]);

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;

    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');

      if (video.readyState === 4 && ctx) {
        // Draw small frame for analysis (reduce bandwidth/latency)
        canvas.width = 320;
        canvas.height = 240;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.6); // Low quality is enough for structure check

        // Show "Scanning" state briefly if we were previously idle
        if (validationStatus === 'searching') setValidationStatus('analyzing');

        const result = await analyzeIDPhotoFrame(base64);

        if (!result.faceDetected) {
           setValidationStatus('searching');
           setFeedbackMessage('Không tìm thấy mặt');
           setInstruction('Di chuyển vào khung hình');
        } else if (result.isCompliant) {
           setValidationStatus('valid');
           setFeedbackMessage('ĐẠT CHUẨN');
           setInstruction(result.instruction || 'Giữ nguyên tư thế!');
        } else {
           setValidationStatus('adjusting');
           setFeedbackMessage(result.feedback || 'Cần điều chỉnh');
           setInstruction(result.instruction || 'Chỉnh lại tư thế');
        }
      }
    } catch (err) {
      console.error("AI check failed", err);
    } finally {
      isAnalyzingRef.current = false;
    }
  };

  const getDevices = async () => {
    try {
      const allDevices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = allDevices.filter(device => device.kind === 'videoinput');
      setDevices(videoDevices);
      const canon = videoDevices.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
      if (canon) setSelectedDeviceId(canon.deviceId);
    } catch (err) {
      console.error("Error enumerating devices", err);
    }
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints: MediaStreamConstraints = {
        video: {
          deviceId: deviceId ? { exact: deviceId } : undefined,
          width: { ideal: 1920 }, // High resolution for quality crop
          height: { ideal: 1080 },
        },
        audio: false
      };
      const mediaStream = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(mediaStream);
      if (videoRef.current) videoRef.current.srcObject = mediaStream;
      setError('');
    } catch (err) {
      setError('Không thể truy cập camera. Kiểm tra kết nối.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const captureFrame = useCallback(() => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (context && video.videoWidth > 0 && video.videoHeight > 0) {
        // Crop logic...
        let targetRatio = 2/3; // Default 4x6
        if (selectedSize === PhotoSize.SIZE_5X5) targetRatio = 1;
        if (selectedSize === PhotoSize.SIZE_3X4) targetRatio = 3/4;

        const videoRatio = video.videoWidth / video.videoHeight;

        let sourceW, sourceH, startX, startY;

        if (videoRatio > targetRatio) {
          sourceH = video.videoHeight;
          sourceW = sourceH * targetRatio;
          startX = (video.videoWidth - sourceW) / 2;
          startY = 0;
        } else {
          sourceW = video.videoWidth;
          sourceH = sourceW / targetRatio;
          startX = 0;
          startY = (video.videoHeight - sourceH) / 2;
        }

        canvas.width = sourceW;
        canvas.height = sourceH;

        // Mirror effect for selfie camera
        context.translate(canvas.width, 0);
        context.scale(-1, 1); 

        context.drawImage(video, startX, startY, sourceW, sourceH, 0, 0, canvas.width, canvas.height);

        const dataUrl = canvas.toDataURL('image/jpeg', 1.0);
        onCapture(dataUrl);
      }
    }
  }, [onCapture, selectedSize]);

  useEffect(() => {
    if (countdown === null) return;

    if (countdown > 0) {
      const timer = setTimeout(() => {
        setCountdown(countdown - 1);
      }, 1000);
      return () => clearTimeout(timer);
    } else if (countdown === 0) {
      captureFrame();
      setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleCaptureClick = () => {
    // Allows manual override if AI is stuck, but encourages valid state
    setCountdown(3);
  };

  const isUSVisa = selectedSize === PhotoSize.SIZE_5X5;
  const is3x4 = selectedSize === PhotoSize.SIZE_3X4;

  // Determine UI Colors based on Strict State
  const getStatusColor = () => {
    switch (validationStatus) {
      case 'valid': return 'border-green-500 shadow-[0_0_30px_rgba(34,197,94,0.6)]';
      case 'adjusting': return 'border-yellow-400 shadow-[0_0_20px_rgba(250,204,21,0.4)]';
      case 'analyzing': return 'border-blue-400 shadow-[0_0_20px_rgba(96,165,250,0.4)]';
      case 'searching': 
      default: return 'border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.6)]';
    }
  };

  const getOverlayColor = () => {
     switch (validationStatus) {
      case 'valid': return '#22c55e'; // Green
      case 'adjusting': return '#facc15'; // Yellow
      case 'analyzing': return '#60a5fa'; // Blue
      default: return '#ef4444'; // Red
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full bg-gray-900 relative select-none">

      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 z-50 p-4 flex justify-between items-start bg-gradient-to-b from-black/80 to-transparent pb-12">
        <select 
          value={selectedDeviceId}
          onChange={(e) => setSelectedDeviceId(e.target.value)}
          className="bg-black/50 text-white text-xs border border-gray-600 rounded px-3 py-1.5 outline-none backdrop-blur-md pointer-events-auto"
        >
          <option value="">-- Chọn Camera --</option>
          {devices.map((device, idx) => (
            <option key={device.deviceId || idx} value={device.deviceId}>
              {device.label || `Camera ${idx + 1}`}
            </option>
          ))}
        </select>

        {/* Realtime Feedback Status - LARGE & CENTRAL */}
        <div className={`
          absolute top-16 left-1/2 transform -translate-x-1/2
