import React, { useState } from 'react';
import { PhotoSettings, PhotoSize } from '../types';
import { savePhotoToCloud } from '../services/databaseService';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
  onHome: () => void;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, 
  size, 
  settings, 
  onBack, 
  onNew,
  onSaved,
  onHome
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  // Zalo & QR State
  const [phoneNumber, setPhoneNumber] = useState(settings.phoneNumber || '');
  const [isSendingZalo, setIsSendingZalo] = useState(false);
  const [showQR, setShowQR] = useState(false);

  // Grid config logic
  const is3x4 = size === PhotoSize.SIZE_3X4;
  const is5x5 = size === PhotoSize.SIZE_5X5;

  let cellWidth = '37mm';
  let cellHeight = '57mm';
  let totalPhotos = 8;

  if (is3x4) {
    cellWidth = '27mm';
    cellHeight = '37mm';
    totalPhotos = 16;
  } else if (is5x5) {
    cellWidth = '49mm';
    cellHeight = '49mm';
    totalPhotos = 6;
  }

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = () => {
    const link = document.createElement('a');
    link.href = processedImage;
    link.download = `ID-Photo-${size}-${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSaveToDB = async () => {
    setIsSaving(true);
    const currentSettings = { ...settings, phoneNumber };
    const success = await savePhotoToCloud({
      id: Date.now().toString(),
      dataUrl: processedImage,
      timestamp: Date.now(),
      settings: currentSettings
    });
    setIsSaving(false);
    if (success) {
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
      if (onSaved) onSaved();
    } else {
      alert("Lỗi khi lưu vào cơ sở dữ liệu");
    }
  };

  const handleSendZalo = async () => {
    if (!phoneNumber || phoneNumber.length < 9) {
      alert("Vui lòng nhập số điện thoại hợp lệ.");
      return;
    }
    setIsSendingZalo(true);
    try {
      console.log("Đang gửi Zalo tới:", phoneNumber);
      await new Promise(resolve => setTimeout(resolve, 1500)); 
      alert(`Đã gửi ảnh thành công tới Zalo: ${phoneNumber}`);
    } catch (error) {
      alert("Gửi thất bại. Vui lòng thử lại.");
    } finally {
      setIsSendingZalo(false);
    }
  };

  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=https://photobooth-demo.com/download/photo-${Date.now()}`;

  return (
    <div className="flex flex-col h-full bg-slate-100 relative">

      {/* QR Code Modal */}
      {showQR && (
        <div className="fixed inset-0 z-50 bg-black/60 flex items-center justify-center p-4 backdrop-blur-sm" onClick={() => setShowQR(false)}>
          <div className="bg-white rounded-2xl p-6 max-w-sm w-full shadow-2xl text-center transform transition-all scale-100" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-bold text-gray-800 mb-2">Quét mã để tải ảnh</h3>
            <p className="text-sm text-gray-500 mb-4">Sử dụng Camera hoặc Zalo để quét</p>

            <div className="bg-white p-2 rounded-xl border-2 border-brand-100 inline-block mb-4 shadow-inner">
               <img src={qrCodeUrl} alt="QR Download" className="w-48 h-48 mix-blend-multiply" />
            </div>
            <button onClick={() => setShowQR(false)} className="w-full py-3 bg-gray-100 hover:bg-gray-200 text-gray-800 rounded-xl font-bold transition">Đóng</button>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="bg-white shadow-sm p-4 flex justify-between items-center no-print z-20">
        <h1 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
          <svg className="w-6 h-6 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
          Print Preview <span className="text-xs bg-slate-100 px-2 py-0.5 rounded text-slate-500 font-normal">Epson L8050 Mode</span>
        </h1>
        <div className="flex gap-3">
          <button onClick={onBack} className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg transition">Chỉnh sửa lại</button>
          <button onClick={onNew} className="px-4 py-2 text-sm font-bold text-white bg-slate-800 hover:bg-black rounded-lg transition shadow-md">Khách mới</button>
        </div>
      </header>

      <div className="flex-1 overflow-hidden flex justify-center items-start gap-8 p-8">

        {/* Print Canvas Container */}
        <div className="h-full overflow-auto flex items-center justify-center scrollbar-hide">
            <div 
              className="bg-white shadow-2xl overflow-hidden relative print:shadow-none transform transition-transform origin-top hover:scale-[1.01]" 
              style={{ 
                width: '130mm', 
                height: '180mm', 
                minWidth: '130mm', 
                minHeight: '180mm',
                border: '1px solid #e5e7eb'
              }}
            >
                {/* Grid Layout */}
                <div className={`w-full h-full p-[5mm] flex flex-wrap content-start gap-[2mm] ${is5x5 ? 'justify-center content-center' : ''}`}>
                  {Array.from({ length: totalPhotos }).map((_, i) => (
                    <div 
                      key={i} 
                      className="overflow-hidden border border-gray-100 bg-gray-50"
                      style={{ width: cellWidth, height: cellHeight }}
                    >
                      <img src={processedImage} className="w-full h-full object-cover" alt="ID Photo" />
                    </div>
                  ))}
                </div>
                <div className="absolute bottom-1 right-2 text-[8px] text-gray-300 print:text-gray-100 font-mono">ID PHOTO BOOTH PRO • {size} • {new Date().toLocaleDateString()}</div>
            </div>
        </div>

        {/* Action Panel - Right Sidebar */}
        <div className="w-80 bg-white p-6 rounded-2xl shadow-xl flex flex-col gap-6 no-print h-fit">

          {/* PRIMARY ACTION: PRINT */}
          <div>
            <div className="flex justify-between items-center mb-4">
               <h3 className="font-bold text-gray-800">Thao tác chính</h3>
               <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded-full font-bold">{totalPhotos} ảnh/trang</span>
            </div>

            <button 
              onClick={handlePrint}
              className="group w-full py-4 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold text-lg shadow-lg hover:shadow-xl transition-all flex flex-col items-center justify-center gap-1"
            >
              <div className="flex items-center gap-2">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                <span>IN NGAY</span>
              </div>
              <span className="text-[10px] opacity-80 font-normal">Kết nối máy in (Ctrl + P)</span>
            </button>

            <button 
              onClick={handleSaveToDB}
              disabled={isSaving || saveSuccess}
              className={`mt-3 w-full py-2.5 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${
                saveSuccess ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-gray-50 hover:bg-gray-100 text-gray-700 border border-gray-200'
              }`}
            >
              {isSaving ? <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"></div> : 
               saveSuccess ? <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg> : 
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-3m-1 4l-3 3m0 0l-3-3m3 3V4"></path></svg>}
              {isSaving ? 'Đang lưu...' : saveSuccess ? 'Đã lưu CSDL' : 'Lưu vào Gallery'}
            </button>
          </div>

          <hr className="border-gray-100" />

          {/* SECONDARY ACTIONS: SHARE */}
          <div>
             <h3 className="font-bold text-gray-800 mb-3 text-sm uppercase tracking-wider text-gray-400">Gửi File Mềm</h3>

            {/* Zalo Input */}
            <div className="bg-blue-50/50 p-3 rounded-xl border border-blue-100 mb-3">
              <label className="block text-xs font-bold text-blue-800 mb-2 flex items-center gap-1">
                <span className="w-4 h-4 bg-blue-600 text-white rounded-full flex items-center justify-center text-[8px]">Z</span>
                Gửi qua Zalo OA
              </label>
              <div className="flex gap-2">
                <input 
                  type="tel" 
                  value={phoneNumber}
                  onChange={(e) => setPhoneNumber(e.target.value)}
                  placeholder="09xx..." 
                  className="flex-1 min-w-0 bg-white border border-blue-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                />
                <button 
                  onClick={handleSendZalo}
                  disabled={isSendingZalo || !phoneNumber}
                  className="px-3 py-2 bg-blue-600 text-white rounded-lg font-bold text-xs hover:bg-blue-700 shadow-sm transition"
                >
                  Gửi
                </button>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3 mb-3">
              <button 
                onClick={handleDownload}
                className="flex flex-col items-center justify-center gap-1 p-3 border border-slate-200 rounded-xl hover:bg-slate-50 hover:border-slate-300 transition text-slate-600"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
                <span className="text-xs font-bold">Tải về</span>
              </button>

              <button 
                onClick={() => setShowQR(true)}
                className="flex flex-col items-center justify-center gap-1 p-3 border border-slate-200 rounded-xl hover:bg-slate-50 hover:border-slate-300 transition text-slate-600"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v1m6 11h2m-6 0h-2v4h2v-4zM6 8v4M6 20v-4m0 0H4m2 0h2m12-10V6a2 2 0 00-2-2H6a2 2 0 00-2 2v4m16 0v4m0 0h-2m2 0h2M12 20h2m-2-4v4m0 0h-2"></path></svg>
                <span className="text-xs font-bold">QR Code</span>
              </button>
            </div>

             <button 
                onClick={onHome}
                className="w-full flex items-center justify-center gap-2 p-2 text-xs font-bold text-gray-400 hover:text-gray-600 transition"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
                Về trang chủ
              </button>
          </div>
        </div>

      </div>
    </div>
  );
};

