interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
  onHome: () => void;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, 
  size, 
  settings, 
  onBack, 
  onNew,
  onSaved,
  onHome
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [downloadProcessing, setDownloadProcessing] = useState(false);

  // Zalo & QR State
  const [phoneNumber, setPhoneNumber] = useState(settings.phoneNumber || '');
  const [isSendingZalo, setIsSendingZalo] = useState(false);
  const [showQR, setShowQR] = useState(false);
  const [photoId] = useState(`ID-${Date.now().toString().slice(-6)}`);

  // Configuration constants
  const DPI = 300; // Print resolution
  const mmToPx = (mm: number) => (mm / 25.4) * DPI;

  // Grid Layout Logic
  const getLayoutConfig = () => {
    if (size === PhotoSize.SIZE_3X4) {
      return {
        cols: 4,
        rows: 4,
        photoW_mm: 30,
        photoH_mm: 40,
        rotated: false,
        maxOnSheet: 16
      };
    } else if (size === PhotoSize.SIZE_5X5) {
      return {
        cols: 2,
        rows: 3,
        photoW_mm: 50,
        photoH_mm: 50,
        rotated: false,
        maxOnSheet: 6
      };
    } else {
      // 4x6 Default - Rotated to Landscape on sheet for efficiency (2x4=8)
      return {
        cols: 2,
        rows: 4,
        photoW_mm: 60, // Slot width (rotated 4x6)
        photoH_mm: 40, // Slot height
        rotated: true, // Needs CSS rotation
        maxOnSheet: 8
      };
    }
  };

  const layout = getLayoutConfig();
  const photosToRender = Math.min(settings.printQuantity, layout.maxOnSheet);

  // Generate QR Data
  const qrDataUrl = `https://photobooth-demo.com/d/${photoId}`;
  const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(qrDataUrl)}&color=000000&bgcolor=FFFFFF&margin=0`;

  const handlePrint = () => {
    window.print();
  };

  const handleDownloadSingle = () => {
    const link = document.createElement('a');
    link.href = processedImage;
    link.download = `${photoId}-Single.jpg`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  /**
   * Generates a high-res canvas of the 13x18 sheet and downloads it.
   */
  const handleDownloadSheet = async () => {
    setDownloadProcessing(true);

    try {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error("No Canvas Context");

      const width = Math.round(mmToPx(130));
      const height = Math.round(mmToPx(180));

      canvas.width = width;
      canvas.height = height;

      // 1. Draw White Background
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, width, height);

      // 2. Load Photo
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.src = processedImage;
      await new Promise((resolve, reject) => {
        img.onload = resolve;
        img.onerror = reject;
      });

      // 3. Draw Grid
      const photoSlotW = Math.round(mmToPx(layout.photoW_mm));
      const photoSlotH = Math.round(mmToPx(layout.photoH_mm));

      const totalContentW = layout.cols * photoSlotW;
      const startX = (width - totalContentW) / 2;
      const startY = Math.round(mmToPx(5)); // 5mm top margin

      for (let i = 0; i < photosToRender; i++) {
        const col = i % layout.cols;
        const row = Math.floor(i / layout.cols);
        const x = startX + col * photoSlotW;
        const y = startY + row * photoSlotH;

        // Draw cut lines
        ctx.strokeStyle = '#e5e7eb';
        ctx.lineWidth = 2;
        ctx.strokeRect(x, y, photoSlotW, photoSlotH);

        // Draw Image
        if (layout.rotated) {
          // Rotate 90 degrees CCW to fit portrait photo into landscape slot
          ctx.save();
          ctx.translate(x + photoSlotW / 2, y + photoSlotH / 2);
          ctx.rotate(-90 * Math.PI / 180);
          ctx.drawImage(img, -photoSlotH / 2, -photoSlotW / 2, photoSlotH, photoSlotW);
          ctx.restore();
        } else {
          ctx.drawImage(img, x, y, photoSlotW, photoSlotH);
        }
      }

      // 4. Draw Footer Area
      const footerH = Math.round(mmToPx(20)); // 20mm footer
      const footerY = height - footerH;

      ctx.fillStyle = '#f1f5f9'; // Slate-100
      ctx.fillRect(0, footerY, width, footerH);

      // Footer Logo Text
      ctx.fillStyle = '#1e293b'; // Slate-800
      ctx.font = 'bold 50px sans-serif';
      ctx.fillText("ID PHOTO BOOTH", Math.round(mmToPx(8)), footerY + Math.round(mmToPx(8)));

      // Footer Info
      ctx.fillStyle = '#64748b'; // Slate-500
      ctx.font = '40px sans-serif';
      const dateStr = new Date().toLocaleDateString('vi-VN');
      ctx.fillText(`ID: ${photoId}  |  Date: ${dateStr}`, Math.round(mmToPx(8)), footerY + Math.round(mmToPx(14)));

      // Footer QR Code
      const qrImg = new Image();
      qrImg.crossOrigin = "anonymous";
      qrImg.src = qrImageUrl;
      await new Promise((resolve) => {
        qrImg.onload = resolve;
        qrImg.onerror = resolve; // Continue even if QR fails
      });

      const qrSize = Math.round(mmToPx(16));
      ctx.drawImage(qrImg, width - qrSize - Math.round(mmToPx(5)), footerY + Math.round(mmToPx(2)), qrSize, qrSize);

      // 5. Download
      const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = `${photoId}-Sheet.jpg`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

    } catch (error) {
      console.error("Sheet generation failed", error);
      alert("Lỗi tạo ảnh khổ in. Vui lòng thử lại.");
    } finally {
      setDownloadProcessing(false);
    }
  };

  const handleSaveToDB = async () => {
    setIsSaving(true);
    const currentSettings = { ...settings, phoneNumber };
    const success = await savePhotoToCloud({
      id: photoId,
      dataUrl: processedImage,
      timestamp: Date.now(),
      settings: currentSettings
    });
    setIsSaving(false);
    if (success) {
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
      if (onSaved) onSaved();
    } else {
      alert("Lỗi khi lưu vào cơ sở dữ liệu");
    }
  };

  const handleSendZalo = async () => {
    if (!phoneNumber || phoneNumber.length < 9) {
      alert("Vui lòng nhập số điện thoại hợp lệ.");
      return;
    }
    setIsSendingZalo(true);
    setTimeout(() => {
      setIsSendingZalo(false);
      alert(`Đã gửi ảnh thành công tới Zalo: ${phoneNumber}`);
    }, 1500);
  };

  // Styles for the visible DOM preview (mimicking the canvas layout)
  const cellW = layout.photoW_mm + 'mm';
  const cellH = layout.photoH_mm + 'mm';

  return (
    <div className="flex flex-col h-full bg-slate-100 relative">

      {/* QR Code Modal */}
      {showQR && (
        <div className="fixed inset-0 z-50 bg-black/60 flex items-center justify-center p-4 backdrop-blur-sm" onClick={() => setShowQR(false)}>
          <div className="bg-white rounded-2xl p-6 max-w-sm w-full shadow-2xl text-center transform transition-all scale-100" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-bold text-gray-800 mb-2">Quét mã để tải ảnh</h3>
            <p className="text-sm text-gray-500 mb-4">Sử dụng Camera hoặc Zalo để quét</p>

            <div className="bg-white p-2 rounded-xl border-2 border-brand-100 inline-block mb-4 shadow-inner">
               <img src={qrImageUrl} alt="QR Download" className="w-48 h-48 mix-blend-multiply" />
            </div>
            <p className="font-mono text-xs text-gray-400 mb-4">{photoId}</p>
            <button onClick={() => setShowQR(false)} className="w-full py-3 bg-gray-100 hover:bg-gray-200 text-gray-800 rounded-xl font-bold transition">Đóng</button>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="bg-white shadow-sm p-4 flex justify-between items-center no-print z-20">
        <h1 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">
          <svg className="w-6 h-6 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
          Print Preview <span className="text-xs bg-slate-100 px-2 py-0.5 rounded text-slate-500 font-normal">Paper: 13x18cm</span>
        </h1>
        <div className="flex gap-3">
          <button onClick={onBack} className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg transition">Chỉnh sửa lại</button>
