import React, { createContext, useContext, useState, useEffect } from 'react';
import { AppConfig, DEFAULT_CONFIG } from '../types';

interface ConfigContextType {
  config: AppConfig;
  updateConfig: (newConfig: AppConfig) => void;
  resetConfig: () => void;
}

const ConfigContext = createContext<ConfigContextType | undefined>(undefined);

// Helper to lighten/darken hex color (Simple version for demo)
function adjustColor(color: string, amount: number) {
    return '#' + color.replace(/^#/, '').replace(/../g, color => ('0' + Math.min(255, Math.max(0, parseInt(color, 16) + amount)).toString(16)).substr(-2));
}

// Helper to generate palette and set CSS variables
const applyTheme = (hexColor: string) => {
  const root = document.documentElement;
  // This is a simplified palette generator. Real implementation would use HSL.
  // We assume the user picks the "600" value.
  root.style.setProperty('--brand-600', hexColor);
  root.style.setProperty('--brand-700', adjustColor(hexColor, -20)); // Darker
  root.style.setProperty('--brand-500', adjustColor(hexColor, 20));  // Lighter
  root.style.setProperty('--brand-100', adjustColor(hexColor, 180)); // Very Light (Tint)
  root.style.setProperty('--brand-50', adjustColor(hexColor, 200));  // Almost White
};

export const ConfigProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [config, setConfig] = useState<AppConfig>(DEFAULT_CONFIG);

  useEffect(() => {
    const saved = localStorage.getItem('app_config');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setConfig({ ...DEFAULT_CONFIG, ...parsed });
        applyTheme(parsed.brandColor);
      } catch (e) {
        console.error("Failed to load config", e);
      }
    } else {
      applyTheme(DEFAULT_CONFIG.brandColor);
    }
  }, []);

  const updateConfig = (newConfig: AppConfig) => {
    setConfig(newConfig);
    localStorage.setItem('app_config', JSON.stringify(newConfig));
    applyTheme(newConfig.brandColor);
  };

  const resetConfig = () => {
    updateConfig(DEFAULT_CONFIG);
  };

  return (
    <ConfigContext.Provider value={{ config, updateConfig, resetConfig }}>
      {children}
    </ConfigContext.Provider>
  );
};

export const useConfig = () => {
  const context = useContext(ConfigContext);
  if (!context) throw new Error("useConfig must be used within ConfigProvider");
  return context;
};

