            <div className="bg-white p-2 rounded-xl border-2 border-brand-100 inline-block mb-4 shadow-inner">
               <img src={qrImageUrl} alt="QR Download" className="w-48 h-48 mix-blend-multiply" />
            </div>
            {/* Removed the ID display text here as well */}
            <button onClick={() => setShowQR(false)} className="w-full mt-4 py-3 bg-gray-100 hover:bg-gray-200 text-gray-800 rounded-xl font-bold transition">Đóng</button>
