          <button onClick={onBack} className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg transition">Chỉnh sửa lại</button>
          <button onClick={onNew} className="px-4 py-2 text-sm font-bold text-white bg-slate-800 hover:bg-black rounded-lg transition shadow-md">Khách mới</button>
        </div>
      </header>

      <div className="flex-1 overflow-hidden flex justify-center items-start gap-8 p-8">

        {/* Print Canvas DOM Container (Visual Preview) */}
        <div className="h-full overflow-auto flex items-center justify-center scrollbar-hide">
            {/* The Sheet */}
            <div 
              className="bg-white shadow-2xl overflow-hidden relative print:shadow-none flex flex-col print:fixed print:top-0 print:left-0 print:m-0" 
              style={{ 
                width: '130mm', 
                height: '180mm', 
                minWidth: '130mm', 
                minHeight: '180mm',
                border: '1px solid #e5e7eb'
              }}
            >
                {/* Photo Grid Area (Top 160mm) */}
                <div 
                  className="w-full flex-1 flex flex-wrap content-start items-start justify-center"
                  style={{ paddingTop: '5mm', paddingBottom: '0' }} // 5mm top margin
                >
                  {Array.from({ length: photosToRender }).map((_, i) => (
                    <div 
                      key={i} 
                      className="overflow-hidden border border-dashed border-gray-200"
                      style={{ 
                        width: cellW, 
                        height: cellH,
                        // If rotated, we use flex center to hold the rotated image
                        display: layout.rotated ? 'flex' : 'block',
                        alignItems: 'center',
                        justifyContent: 'center'
                      }}
                    >
                      <img 
                        src={processedImage} 
                        className="object-cover" 
                        style={{
                           width: layout.rotated ? 'auto' : '100%',
                           height: layout.rotated ? '100%',
                           // CSS visual rotation to match print logic
                           transform: layout.rotated ? 'rotate(-90deg)' : 'none',
                           // For rotated images, the width becomes the height visually
                           aspectRatio: layout.rotated ? '2/3' : 'auto' 
                        }}
                        alt="ID Photo" 
                      />
                    </div>
                  ))}
                </div>

                {/* Footer Area (Bottom 20mm) */}
                <div className="h-[20mm] bg-slate-50 border-t border-slate-200 flex items-center justify-between px-6">
                    <div>
                       {/* REMOVED "ID" PREFIX, Use Config Text */}
                       <h3 className="font-bold text-slate-800 text-lg leading-tight uppercase">{config.footerText || "PHOTO BOOTH"}</h3>
                       <p className="text-xs text-slate-500 font-mono mt-0.5">Date: {new Date().toLocaleDateString('vi-VN')}</p>
                    </div>
                    <div className="bg-white p-1 rounded border border-slate-200">
                        <img src={qrImageUrl} className="w-[14mm] h-[14mm] mix-blend-multiply opacity-90" alt="QR" />
                    </div>
                </div>
            </div>
        </div>

        {/* Action Panel - Right Sidebar */}
        <div className="w-80 bg-white p-6 rounded-2xl shadow-xl flex flex-col gap-6 no-print h-fit">

          {/* PRIMARY ACTION: PRINT */}
          <div>
            <div className="flex justify-between items-center mb-4">
               <h3 className="font-bold text-gray-800">Thao tác chính</h3>
               <span className="text-xs bg-green-100 text-green-700 px-2 py-1 rounded-full font-bold">{settings.printQuantity} ảnh/tờ</span>
            </div>

            <button 
              onClick={handlePrint}
              className="group w-full py-4 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold text-lg shadow-lg hover:shadow-xl transition-all flex flex-col items-center justify-center gap-1"
            >
              <div className="flex items-center gap-2">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                <span>IN NGAY</span>
              </div>
              <span className="text-[10px] opacity-80 font-normal">Kết nối máy in (Ctrl + P)</span>
            </button>

            <button 
              onClick={handleSaveToDB}
              disabled={isSaving || saveSuccess}
              className={`mt-3 w-full py-2.5 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${
                saveSuccess ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-gray-50 hover:bg-gray-100 text-gray-700 border border-gray-200'
              }`}
            >
              {isSaving ? <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"></div> : 
               saveSuccess ? <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg> : 
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-3m-1 4l-3 3m0 0l-3-3m3 3V4"></path></svg>}
              {isSaving ? 'Đang lưu...' : saveSuccess ? 'Đã lưu CSDL' : 'Lưu vào Gallery'}
            </button>
          </div>

          <hr className="border-gray-100" />

          {/* DOWNLOAD ACTIONS */}
          <div>
             <h3 className="font-bold text-gray-800 mb-3 text-sm uppercase tracking-wider text-gray-400">Tải File</h3>

             <div className="grid grid-cols-2 gap-3 mb-3">
              <button 
                onClick={handleDownloadSingle}
                className="flex flex-col items-center justify-center gap-1 p-3 border border-slate-200 rounded-xl hover:bg-blue-50 hover:border-blue-200 hover:text-blue-700 transition text-slate-600 group"
              >
                <svg className="w-6 h-6 group-hover:-translate-y-0.5 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
                <div className="text-xs font-bold">1. Ảnh lẻ</div>
                <div className="text-[9px] text-gray-400 font-normal">Chỉ ảnh chân dung</div>
              </button>

              <button 
                onClick={handleDownloadSheet}
                disabled={downloadProcessing}
                className="flex flex-col items-center justify-center gap-1 p-3 border border-slate-200 rounded-xl hover:bg-purple-50 hover:border-purple-200 hover:text-purple-700 transition text-slate-600 group relative"
              >
                {downloadProcessing && <div className="absolute inset-0 bg-white/80 flex items-center justify-center rounded-xl"><div className="w-5 h-5 border-2 border-purple-500 border-t-transparent rounded-full animate-spin"/></div>}
                <svg className="w-6 h-6 group-hover:-translate-y-0.5 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
                <div className="text-xs font-bold">2. Cả khổ in</div>
                <div className="text-[9px] text-gray-400 font-normal">Kèm Logo & QR</div>
              </button>
            </div>

            {/* Zalo Input */}
            <div className="bg-blue-50/50 p-3 rounded-xl border border-blue-100 mb-3">
              <label className="block text-xs font-bold text-blue-800 mb-2 flex items-center gap-1">
                <span className="w-4 h-4 bg-blue-600 text-white rounded-full flex items-center justify-center text-[8px]">Z</span>
                Gửi Zalo
              </label>
              <div className="flex gap-2">
                <input 
                  type="tel" 
                  value={phoneNumber}
                  onChange={(e) => setPhoneNumber(e.target.value)}
                  placeholder="09xx..." 
                  className="flex-1 min-w-0 bg-white border border-blue-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                />
                <button 
                  onClick={handleSendZalo}
                  disabled={isSendingZalo || !phoneNumber}
                  className="px-3 py-2 bg-blue-600 text-white rounded-lg font-bold text-xs hover:bg-blue-700 shadow-sm transition"
                >
                  Gửi
                </button>
              </div>
            </div>

             <button 
                onClick={onHome}
                className="w-full flex items-center justify-center gap-2 p-2 text-xs font-bold text-gray-400 hover:text-gray-600 transition"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
                Về trang chủ
              </button>
          </div>
        </div>

      </div>
    </div>
  );
};

export default PrintPreview;

import React, { useState, useEffect } from 'react';
import { BackgroundType, PhotoSize } from '../types';
import { useConfig } from '../contexts/ConfigContext';

interface StartScreenProps {
  onStart: (config: { size: PhotoSize; background: BackgroundType; quantity: number }) => void;
  onHome: () => void;
}

