                  <button 
                    onClick={() => setSelectedBg(BackgroundType.BLUE)}
                    className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${
                      selectedBg === BackgroundType.BLUE 
                        ? 'bg-blue-600 text-white shadow-md' 
                        : 'text-gray-500 hover:text-gray-700'
                    }`}
                  >
                    Xanh
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-3">3. Số lượng ảnh in</label>
