                  <div className="flex-1 text-center font-bold text-gray-800 text-lg">{quantity}</div>
                  <button 
                    onClick={() => setQuantity(q => q + 1)}
                    className="w-12 h-full bg-gray-50 hover:bg-gray-100 text-gray-600 font-bold active:bg-gray-200 transition-colors border-l"
